const epoch = new Map();
const epochOf = (n) => epoch.get(n) || 0;

/**
 * THROW THE CURRENT CEREMONY AWAY. The seat keeps its switch and its old sheet;
 * only the run in flight is silenced, and the cooldown is cleared so kickForges
 * may start a fresh one on its next sweep rather than sitting out the 90 seconds
 * a failure buys.
 *
 * @returns {boolean} whether anything was actually in flight
 */
export function kickForge(n) {
    const was = busy.has(n);
    epoch.set(n, epochOf(n) + 1);
    busy.delete(n);
    lastTry.delete(n);
    if (was) console.info("[forge] seat " + n + " was kicked off the forge; "
        + "whatever it answers now is ignored.");
    return was;
}

/** Kick it and start again from the first page, at once. His "reset the timer". */
export function resetForge(n) {
    kickForge(n);
    const seat = loadSeats().find((s) => s.n === n);
    if (!seat || !seat.on) return false;
    const run = epochOf(n);
    busy.set(n, "warming up");
    forgeSeat(seat)
        .then(() => { if (epochOf(n) === run) lastTry.set(n, { ok: true, t: Date.now() }); })
        .catch((e) => {
            console.warn("[forge] " + seat.name + " failed: " + (e && e.message));
            if (epochOf(n) === run) lastTry.set(n, { ok: false, t: Date.now() });
        })
        .finally(() => { if (epochOf(n) === run) busy.delete(n); });
    return true;
}

