export function kickForges() {
    const difficulty = playerDifficulty();
    for (const seat of loadSeats()) {
        if (!seat.on) continue;
        if (busy.has(seat.n)) continue;
        const d = draftOf(seat.n);
        if (d && d.done && d.difficulty === difficulty) continue;
        const cooled = lastTry.get(seat.n);
        if (cooled && Date.now() - cooled.t <
                (cooled.ok ? 30000 : 90000)) continue;
        /*,,. AND A FINISHED RUN ONLY CLEANS UP AFTER ITSELF ,,,
           These three handlers wrote `busy` and `lastTry` for the seat unconditionally, which was harmless
           while a run could only ever end by finishing. A kicked run ends too, later, and its finally then
           deleted the busy entry belonging to whichever ceremony had REPLACED it -- so a fresh forge would
           read as idle, kickForges would start a second one beside it, and the seat would be interviewed
           twice at once. A run that is no longer the seat's run touches nothing. */
        const run = epochOf(seat.n);
