                if (e && e.kicked) return;
                console.warn("[forge] " + seat.name + " failed: "
                    + (e && e.message));
                if (mine()) lastTry.set(seat.n, { ok: false, t: Date.now() });
            })
            .finally(() => { if (mine()) busy.delete(seat.n); });
    }
}

