/* THE PICTURE IS DRAWN TOO (Rose 09-16: "look in the system folder randomize
   those loading screens when loading in game"): his eight Loading*.png from
   Desktop/Systems stand in assets/img/ui as loading1..8, one per entry into
   a world and never the same one twice running, the veil's own law for its
   marks (ui/loadingVeil.js nextLook). The first-start wardrobe screen keeps
   his moon; this is the world's veil only. */
const LOADING_ART = Array.from({ length: 8 }, (_, i) => "assets/img/ui/loading" + (i + 1) + ".png");
let lastLoadingArt = -1;
function nextLoadingArt() {
    let i = 0;
    if (LOADING_ART.length > 1)
        do { i = (Math.random() * LOADING_ART.length) | 0; } while (i === lastLoadingArt);
    lastLoadingArt = i;
    return LOADING_ART[i];
}

