/** Mounts into `root`, returns an unmount (async, it owes the doll). */
export async function mountVoid(root, mountOpts = {}) {
    if (!window.THREE) {
        await new Promise((res, rej) => {
            const s = document.createElement("script");
            s.src = "lib/three.min.js";
            s.onload = res; s.onerror = () => rej(new Error("could not load three"));
            document.head.append(s);
        });
    }
    /* THE MAP IS DATA (Rose 09-10, the atlas): maps/<key>.json when there is
       one, the built-in void when there is not; ?map=<key> picks another and
       &new=1 starts an empty one. world/atlas.js owns the format. */
    const mapQuery = new URLSearchParams(location.search);
    const mapKey = (mountOpts && mountOpts.map) || mapQuery.get("map") || VOID.key;
    const mapLoad = mapQuery.get("new") === "1" && !(mountOpts && mountOpts.map)
        ? { map: Atlas.normalise(Atlas.emptyMap(mapKey)), source: "new" }
        : await Atlas.loadMap(mapKey);
    const MAP = mapLoad.map;
    console.info("[void] map " + MAP.key + " (" + mapLoad.source + "): " + MAP.cells.length
        + " cells, " + MAP.props.length + " props, " + MAP.npcs.length + " npcs"
        + (MAP.hasSky === false ? ", roofed" : "") + (MAP.weather === false ? ", weather held" : "")
        + (MAP.wind === false ? ", still air" : "") + ", biome " + (MAP.biome || "open"));
    /* THE MAP'S SWITCHES (Rose 09-11: "Weather: Enabled, Wind: Enabled"):
       the weather the plan (world/climate.js) is running is the world's;
       what reaches THIS ground is the map's word. skyKind is the kind
       every reader on this map sees: clear under a roof or where weather
       is held off, the plan's own otherwise. calmAir stills the breath
       (cloth, flames, the shove) for a roof or wind: false. Read live,
       so the desk's switch lands without a reload for these two; the sky
       itself (the dome, the sun) is mounted once and takes the next. */
    const calmAir = () => MAP.wind === false || MAP.hasSky === false;
    /* THE MAP'S PAGE IN THE SAVE BOOK (save.js, Rose 09-11 "tackle the
       memory"): what stood here when she left is laid over the file before
       anything is placed, so a felled tree stands felled and an opened
       chest open. The runner's own pages (the things, what lies on the
       ground, her) are registered at the end of this mount, where their
       state lives; the book hands them back once the world stands. */
    Save.enterMap(MAP.key);
    /* set below when this book last saw the map before it was remade: her saved place on
       the old ground means nothing on the new one (her restore reads it) */
    let remadeSinceBook = false;
    {
        const page = Save.mapData(MAP.key);
        if (page && page.things) {
            /* THE BOOK OVERRIDES, BUT IT NO LONGER ERASES (Rose 09-12: "make a
               cabin on the map"). This was a straight assignment once: the
               book's list REPLACED the file's, so anything the map gained
               after a save -- a new building, a new tree, a new person -- was
               invisible to every save already written. Only a brand new game
               ever saw new work, which is no way to build a world you are also
               playing.

               WHAT DECIDES IS THE VERSION IT WAS ADDED AT, NOT WHETHER THE
               BOOK LISTS IT (Rose 09-12: "when I quick load the enemy
               (scarecrow) that I destroyed respawns"). The first cut of this
               asked "does the book know this id?", and the answer is the same
               NO for a thing built yesterday and a thing the player killed
               yesterday -- so it raised the dead. A prop carries the map
               version it was added at, the book remembers the version it last
               saw, and only a prop NEWER than that is something this save has
               genuinely never been offered. A destroyed scarecrow is old and
               stays destroyed; a cabin built today is new and arrives. Saves
               written before any of this carry no version at all, which reads
               as 1, so the original four are never resurrected. */
            const bookVer = +(page.things.mapRev) || 1;
            const join = (savedList, fileList) => {
                const has = new Set(savedList.map((q) => q && q.id));
                return savedList.concat(fileList.filter(
                    (q) => q && !has.has(q.id) && (+q.added || 1) > bookVer));
            };
            /*,,. A MAP REMADE UNDER ITS OLD KEY (Rose 2026-09-23, the void rebuilt as the burned
               village: "Did you think I wanted to keep any of the place holder shit I was using to
               test things in void?") ,,,
               The join above only ever ADDS, which is right for a map that grows and wrong for one
               that was torn down and built again: a book written against the old void carried the
               old chests, dummy, cabin and sacks, and laid them over the new village's ground.
               `remade` is the rev the map was rebuilt at; a book that last saw the map before it
               keeps nothing of the place it knew, and the file's things stand. */
            const remade = +MAP.remade || 0;
            if (remade && bookVer < remade) {
                console.info("[void] " + MAP.key + " was remade at rev " + remade + "; this book knew rev "
                    + bookVer + ", so the map's own things stand");
                remadeSinceBook = true;
            } else {
                if (Array.isArray(page.things.props)) MAP.props = join(page.things.props, MAP.props);
                if (Array.isArray(page.things.npcs)) MAP.npcs = join(page.things.npcs, MAP.npcs);
            }
        }
    }
    /*,,. THE STORY THIS WORLD IS TELLING (Rose 2026-09-23, the seat campaign) ,,,
       Opened before anything is placed, because what stands can depend on it: who is dead, who has joined
       whom. A world with no campaign file opens null, and every NPC keeps its plain greet line. */
    const story = await openStory().catch((e) => {
        console.warn("[void] the story would not open:", e && e.message);
        return null;
    });
    if (story) console.info("[void] story " + story.data.key + ": "
        + Object.keys(story.data.talks || {}).length + " talks, "
        + Object.keys(story.data.quests || {}).length + " quests");
    /* AND WHETHER THIS WORLD WAS WALKED INTO BY A ROAD (the seat campaign): she stands at the entry the
       exit named once the book is read back (placeArrival), and the seats who came with her beside her */
    const arrived = takeArrival(MAP.key);
    if (arrived) console.info("[void] arrived from " + (arrived.from || "somewhere") + " by road, at "
        + (arrived.entry && MAP.entries[arrived.entry] ? arrived.entry : "the spawn"));
    /* THE ROADS BEYOND THIS MAP (world/exitSigns.js): every map its exits lead to, and theirs, read once
       behind the veil, so a way out can say whether a quest's next step lies down it */
    const roads = (MAP.exits && MAP.exits.length)
        ? await readRoads(MAP, (k) => Atlas.loadMap(k)).catch((e) => {
            console.warn("[void] the roads beyond this map would not read:", e && e.message);
            return null;
        })
        : null;
    /* THE FEATS COG'S RULES (src/rules/feats.js since move F1b; they were the feats page's), for the world's people
       (src/npcSheet.js): reached the way the forge reaches them, by a dynamic import */
    const featsGateMod = await import("../rules/feats.js").catch((e) => {
        console.warn("[void] the feats cog would not load; NPCs stand unsheeted:", e && e.message);
        return null;
    });
    let mountedResolve = null;
    const mounted = new Promise((r) => { mountedResolve = r; });
    const AC = new AbortController();
    /* `opts` exists for the WHEEL alone: Chrome registers wheel listeners on
       window as PASSIVE by default, and a passive listener's
       preventDefault() is ignored with a console scolding -- so the zoom
       would work and scroll the page underneath it at the same time. Every
       other caller passes nothing and gets the old behaviour. */
    const on = (t, fn, opts) =>
        addEventListener(t, fn, { signal: AC.signal, ...(opts || {}) });
    let alive = true;

    /* the game-wide right-click law lives in app.js and does not reach the
       standalone dev page, the scene keeps its own (the forest's lesson) */
    on("contextmenu", (e) => e.preventDefault());

    /* A RELOAD IS NOT A SECOND WINDOW. `unmount()` never runs when a page is
       reloaded or closed, so a seat claimed by the outgoing instance stayed
       warm and the INCOMING one was refused its own seat, no body, no talk
       box, and a game that looked like it had simply stopped working. Let go
       of everything on the way out; pagehide fires where unload does not. */
    addEventListener("pagehide", () => {
        for (const m of bodies) { keepPlace(m); dropSeat(m); }
        for (const w of waiting) releaseSeat(w.seat.n, worldId);
        /* AND THE LESSON GOES WITH IT (Rose 09-13: closing the window mid-fight
           must not un-teach what the fight taught). A beacon, not a fetch:
           this is the moment the page stops existing, and an ordinary request
           started here dies with it. battle/learn.js flushBeacon. */
        Learn.flushBeacon();
    });

    root.innerHTML = "";
    root.style.cssText = "position:fixed;inset:0;background:#000000";

    /* THE DOOR SAYS SO NOW (Rose 08-18: "We may need a 'loading' screen",
       then, on being shown ceremony: "just a basic loading in the lower
       right") -- AND SINCE 09-12 IT IS A PICTURE ("port it into the blessed
       lady project replacing -our- loading screen"). The black cover and its
       one word are gone; ui/loadingVeil.js carries the whole of it now, and
       the bench that judges a change to it is the preview page in
       Desktop/Systems/loading-preview.html.

       WHAT THE OLD COVER PROMISED IS KEPT, because the reasons have not
       changed: it is painted BEFORE the synchronous lifting starts (nothing
       painted after that begins would show until it ends), every moving part
       of it is CSS on its own layer so the compositor keeps it breathing
       through a blocked main thread, and the wait below is still raced
       against a short clock because a hidden tab gets no frames at all.

       The place is named because that is the one thing worth reading while
       waiting, and the look is drawn fresh per load (loadingVeil nextLook). */
    const veil = mountLoadingVeil(root);
    await Promise.race([
        veil.show({ place: MAP.name || MAP.key,
                    art: nextLoadingArt(),
                    tip: pickTip(), tipNext: pickTip }),   // a rule of the world while it loads, a fresh one on a long load (data/tips.js)
        new Promise((res) => setTimeout(res, 250)),
    ]);
    /*,,. THE DOOR COUNTS ITS OWN STEPS (Rose 2026-09-27: "the loading screen completes at a 100% and just stays there
       for like 30-45 secs... may not even be the horse, but its something") ,,,
       Nothing in a world's load told the veil how far it had got but the wardrobe's safety net, and a warm wardrobe
       owes nothing and says nothing. So the veil crept on its own to its ceiling (0.92, loadingVeil.js) in five
       seconds, the place name all but written, and sat there looking done through her figure (13.8 s measured that
       day), the map's warm-up (16.9 s, two guests stood) and the rest. Each stage now says where it is:
       veilStage(to, ms) creeps the count toward `to` while a stage runs (four fifths of the way by `ms`, the stage's
       measured length, never all of it), and veilReach(to) lands it when the stage ends. The count never goes backwards
       (veil.progress), and the door lands it at one just before it opens.
       THE SHARES ARE WHAT THE EYE SEES, AND THEY ARE TIME. The chronicle writes the name on an ease-out, so the first
       cut (a stage's share in raw progress) showed 84% written at 18.5 s of a 38.6 s load and then sat. Each share is
       now the part of the name written (loadingVeil.js progressShowing turns it into the veil's count), and each is its
       stage's share of that measured load: her figure 9.6 s, her cloth, the people and the torch 12 s more, the map's
       warm-up 12.6 s. */
    let veilAt = 0, veilTick = 0;
    function veilStage(to, ms) {
        clearInterval(veilTick);
        const from = veilAt, t0 = performance.now();
        veilTick = setInterval(() => {
            if (!alive) { clearInterval(veilTick); return; }
            const k = 1 - Math.exp(-(performance.now() - t0) / (Math.max(500, ms || 5000) / 1.8));
            veilAt = Math.max(veilAt, from + (to - from) * 0.95 * k);
            veil.progress(progressShowing(veilAt));
        }, 150);
    }
    function veilReach(to) {
        clearInterval(veilTick); veilTick = 0;
        veilAt = Math.max(veilAt, to);
        veil.progress(progressShowing(veilAt));
    }
    /* a stage that counts itself (the wardrobe's safety net) counts inside its own share of the bar */
    const veilSpan = (a, b) => ({ note: (t) => veil.note(t), progress: (p) => veilReach(a + (b - a) * Math.max(0, Math.min(1, p))) });
    veilStage(0.26, 10000);            // the map, then her figure
    /* A FERAL EAR HAS ITS WORDS BEFORE ANYONE SPEAKS (herEar, below): the dictionary is read once a page, 3.3 MB,
       started as the veil goes up and waited on before it comes down, and only for a character her flaws silence */
    const feralWarm = herFeral() ? warmFeral() : null;
    /* every mouth says its lines from their text (world/lipText.js): the dictionary's one read begins now, in the
       background; a line said before it lands is read by its letters */
    warmLips();
    /* the autoplay law wants a gesture and the TITLE usually provides it;
       a dev entry straight into the void never visits the title, so the
       first gesture HERE unlocks the bed too (a no-op when already open) */
    addEventListener("pointerdown", unlock, { once: true, signal: AC.signal });
    addEventListener("keydown", unlock, { once: true, signal: AC.signal });
    /* A SAVE REFUSED IS SAID (step 1's move 24c): save.js writes no book whose record is not whole, and tells the world
       why; said once a reason, since a rest and a map's change may both ask */
    const saidRefused = new Set();
    addEventListener("save:refused", (e) => {
        const why = e && e.detail && e.detail.why;
        if (!why || saidRefused.has(why)) return;
        saidRefused.add(why);
        worldSay("Your character could not be saved: " + why + ". Nothing was written.");
    }, { signal: AC.signal });
    /* a fresh evening starts with a clean stance table: the seeded war
       between party and monster, and every other pair neutral. Grudges made
       IN this world persist for its whole life, which is the point. */
    resetStances();
    /* THE HERALD (ui/herald.js). Mounted with the world and not with the
       fight, because the things it announces are not all fights: an invader
       can walk into a quiet evening. It is one veil for the world's whole
       life, takes no pointer events, and is disposed in the teardown below. */
    const herald = mountHerald(document.body, {
        /* the game's own one-shot player: the sfx gain, the chosen output
           device, and a primed buffer so the first one is not the slow one */
        cue: (src, vol) => cue(src, vol),
        /* and the bell it rings when a kind has no file rides the same slider */
        gain: () => gainOf("sfx"),
    });
    /* warm both invasion takes with the world, not at the first invasion --
       a 250 KB fetch is not something to start when the screen is already
       shaking (src/audio.js primeCue) */
    for (const src of (herald.tones.invasion.se || [])) primeCue(src);
    /* and the summon's, for the same reason: it plays on the frame a phantom rises out of the floor, and a
       250 KB fetch started THEN arrives after the thing it was announcing (this was warming the invasion
       alone, so the half of the mechanic he actually uses was the cold one) */
    for (const src of (herald.tones.summon.se || [])) primeCue(src);
    /* and the one that plays when she wins -- warmed for the same reason,
       since it lands on the frame a body falls (battle/revenant.js) */
    for (const src of VICTORY_SE) primeCue(src);

    /* ---------------------------------------------------------- the sign
       HOSTING (Rose 09-13: "we'll test things out by opening two clients on
       two ports or something... then you can test invasions").

       Hanging out a sign says this world is open. After that the only thing
       the host listens for is somebody WALKING IN: a join arrives, and the
       standing it carries is turned into a body by standRevenant -- which is
       the same door the dev handle already used, so an invader from another
       machine and an invader conjured at the console are the same event by
       the time anything in the game sees it.

       THE GUEST NEVER SPAWNS ANYTHING. It asks; the host decides and places.
       That is the whole of "owns the world" in one function. */
    let mpSign = null;              // {code, name} while a sign is out
    let mpStop = null;              // the poller's stop, which must be kept
    const mpGuests = new Map();     // pid -> the world body it is wearing
    /* a turn that has been sent out and is waiting on a person.
       pid -> {resolve, reject, timer} */
    const mpTurns = new Map();

    /** the guest wearing this fighter's body, if one still is */
    /*,,. A GUEST DECIDES ITS OWN TURNS, ON EVERY ROAD INTO A FIGHT ,,,
       battle/ally.js asks nobody unless `actor.mind` is set, and a mind is only
       ever set for an LLM seat -- so a guest arrived with a network address and
       an NPC brain, and the NPC brain played it while the person it belonged to
       watched an empty panel.

       IT TOOK TWO GOES AND THE FIRST LOOKED LIKE A FAILURE, which is the part
       worth keeping. There are two roads into a fight and I paved one:
       joinFight forges a LATECOMER, while startFightOnMap sorts bodies already
       standing into `seated` (m.mind.n != null) or `mindless`. A guest has no
       seat number, so it fell into `mindless` -- the COMMON case, since an
       invader is usually standing there before the fight opens. Patching
       joinFight alone left the ordinary path exactly as broken, and the second
       test read identically to the first. WHEN A FIX CHANGES NOTHING, COUNT
       THE ROADS IN before doubting the fix.

       AND IT MUST RUN AFTER THE PUSH, not before. The call inside joinFight
       originally sat ABOVE b.combatants.push(f), so it marked every guest
       already in the fight and never the one arriving: the latecomer road's
       own call had never once done its job. That survived a month because
       every invasion test had a SINGLE guest, and a single guest comes in by
       the assembly road, which marks correctly. Two at once showed it
