            clearTimeout(w.timer);
            w.resolve(String((m.data && m.data.text) || ""));
            return;
        }
        if (m.t === "leave") {
            /* a turn this guest was holding can never be answered now */
            const w = mpTurns.get(m.from);
            if (w) { mpTurns.delete(m.from); clearTimeout(w.timer);
